// Isolation test (OS-12) — construct ScopeReader with its declared inputs and nothing else, then
// exercise every public operation. (Generated by new-object.py, rewritten for strict TypeScript - MF-21.)
import { describe, expect, it } from "vitest";
import { ScopeReader } from "../src/spend/index.js";
import { inMemoryRecord } from "./catalog/in-memory-record.js";
import { c0, scopeWorld, u } from "./support/spend-parts.js";

describe("ScopeReader in isolation", () => {
  it("refuses to construct when an input is missing", () => {
    expect(() => new ScopeReader({} as never)).toThrow();
  });

  it("refuses inputs that do not offer the operations it calls (OS-1, declared slots)", () => {
    expect(() => new ScopeReader({ record: {} as never })).toThrow();
  });

  it("governing answers differently when record differs", () => {
    const w = scopeWorld();
    w.authorize(c0, 3);
    const h = w.record.noise();
    expect(new ScopeReader({ record: w.record }).governing(u, c0, h)).not.toEqual(new ScopeReader({ record: inMemoryRecord() }).governing(u, c0, h));
  });

  it("scopeAt answers differently when record differs", () => {
    const w = scopeWorld();
    const s = w.authorize(c0, 3);
    const h = w.record.noise();
    expect(new ScopeReader({ record: w.record }).scopeAt(s.at, h)).not.toEqual(new ScopeReader({ record: inMemoryRecord() }).scopeAt(s.at, h));
  });

  it("hasStopCondition reads its argument alone (invariant to record)", () => {
    const w = scopeWorld();
    const plain = w.authorize(c0, 3);
    const stopped = w.authorize(c0, 3, { kind: "stop-at-bar", component: "q" });
    const reader = new ScopeReader({ record: inMemoryRecord() });
    expect([reader.hasStopCondition(plain), reader.hasStopCondition(stopped)]).toEqual([false, true]);
  });
});
